/**
 * This translation layer make sure that we expose codex error code in camel case.
 *
 * When an upstream HTTP status is available (for example, from the Responses API or a provider), it is forwarded in `httpStatusCode` on the relevant `codexErrorInfo` variant.
 */
export const zCodexErrorInfo = z.union([
    z.literal('contextWindowExceeded'),
    z.literal('sessionBudgetExceeded'),
    z.literal('usageLimitExceeded'),
    z.literal('rateLimitExceeded'),
    z.literal('serverOverloaded'),
    z.literal('cyberPolicy'),
    z.literal('misalignmentPolicyViolation'),
    z.literal('internalServerError'),
    z.literal('unauthorized'),
    z.literal('badRequest'),
    z.literal('threadRollbackFailed'),
    z.literal('sandboxError'),
    z.literal('other'),
    z.strictObject({
        httpConnectionFailed: z.looseObject({
            httpStatusCode: z.int().gte(0).max(65535, { error: 'Invalid value: Expected uint16 to be <= 65535' }).nullish()
        })
    }),
    z.strictObject({
        responseStreamConnectionFailed: z.looseObject({
            httpStatusCode: z.int().gte(0).max(65535, { error: 'Invalid value: Expected uint16 to be <= 65535' }).nullish()
        })
    }),
    z.strictObject({
        responseStreamDisconnected: z.looseObject({
            httpStatusCode: z.int().gte(0).max(65535, { error: 'Invalid value: Expected uint16 to be <= 65535' }).nullish()
        })
    }),
    z.strictObject({
        responseTooManyFailedAttempts: z.looseObject({
            httpStatusCode: z.int().gte(0).max(65535, { error: 'Invalid value: Expected uint16 to be <= 65535' }).nullish()
        })
    }),
    z.strictObject({
        activeTurnNotSteerable: z.looseObject({
            turnKind: zNonSteerableTurnKind
        })
    })
]);

