export const zWorkspaceMessageType = z.enum([
    'headline',
    'announcement',
    'unknown'
]);

export const zWorkspaceMessage = z.looseObject({
    archivedAt: z.int().nullish(),
    createdAt: z.int().nullish(),
    messageBody: z.string(),
    messageId: z.string(),
    messageType: zWorkspaceMessageType
});

/**
 * GetWorkspaceMessagesResponse
 */
export const zGetWorkspaceMessagesResponse = z.looseObject({
    featureEnabled: z.boolean(),
    messages: z.array(zWorkspaceMessage)
});

export const zWriteStatus = z.enum(['ok', 'okOverridden']);

/**
 * ConfigWriteResponse
 */
export const zConfigWriteResponse = z.looseObject({
    filePath: zAbsolutePathBuf,
    overriddenMetadata: zOverriddenMetadata.nullish(),
    status: zWriteStatus,
    version: z.string()
});
